#include <vector>

class Solution {
public:
    std::vector<int> targetIndices(std::vector<int>& nums, int target) {
        int lessCount = 0;
        int targetCount = 0;

        for (int x : nums) {
            if (x < target) lessCount++;
            else if (x == target) targetCount++;
        }

        std::vector<int> ans;
        for (int i = 0; i < targetCount; ++i) {
            ans.push_back(lessCount + i);
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> targetIndices(int[] nums, int target) {
        int lessCount = 0;
        int targetCount = 0;

        for (int x : nums) {
            if (x < target) lessCount++;
            else if (x == target) targetCount++;
        }

        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < targetCount; i++) {
            ans.add(lessCount + i);
        }
        return ans;
    }
}

