var targetIndices = function(nums, target) {
    let lessCount = 0;
    let targetCount = 0;

    for (const x of nums) {
        if (x < target) lessCount++;
        else if (x === target) targetCount++;
    }

    const ans = [];
    for (let i = 0; i < targetCount; i++) {
        ans.push(lessCount + i);
    }
    return ans;
};
